import csv
import sys


def count_orders(path: str) -> int:
    """Return the number of data rows in a CSV. Raise FileNotFoundError
    with a clear message if the path does not resolve; ValueError if
    the header is missing an 'order_id' column."""
    try:
        with open(path, newline="") as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None or "order_id" not in reader.fieldnames:
                raise ValueError(f"{path}: expected an 'order_id' column")
            return sum(1 for _ in reader)
    except FileNotFoundError:
        raise FileNotFoundError(f"no such file: {path} (check your pwd)")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit("usage: python solution.py <path-to-csv>")
    print(count_orders(sys.argv[1]))

