def parse_grades(rows):
    """rows: list[str] like 'Ada,90'. Returns {'count', 'average', 'top'}."""
    if not rows:
        raise ValueError("no rows given")
    grades = {}
    for row in rows:
        name, _, raw = row.partition(",")
        if not raw:
            raise ValueError(f"missing score in row: {row!r}")
        grades[name] = float(raw)
    scores = list(grades.values())
    return {
        "count": len(scores),
        "average": sum(scores) / len(scores),
        "top": max(grades, key=grades.get),
    }

