from dataclasses import dataclass


@dataclass(frozen=True)
class Order:
    sku: str
    quantity: int
    unit_price: float

    def __post_init__(self) -> None:
        if not isinstance(self.quantity, int) or isinstance(self.quantity, bool):
            raise TypeError(f"quantity must be int, got {type(self.quantity).__name__}")
        if self.quantity <= 0:
            raise ValueError(f"quantity must be positive, got {self.quantity}")
        if self.unit_price < 0:
            raise ValueError(f"unit_price must be >= 0, got {self.unit_price}")

    @property
    def total(self) -> float:
        return self.quantity * self.unit_price


def parse_order(row: dict) -> Order:
    """Build a validated Order from a raw dict; missing keys raise KeyError."""
    return Order(sku=row["sku"], quantity=row["quantity"], unit_price=row["unit_price"])

