class OrderError(ValueError):
    """Raised when an order record fails validation."""


def validate_order(row: dict) -> dict:
    """Contract: row has 'sku' (str), 'qty' (int>0), 'price' (float>=0).
    Returns a clean typed dict, or raises OrderError naming the field.
    """
    required = {"sku", "qty", "price"}
    missing = required - row.keys()
    if missing:
        raise OrderError(f"missing fields: {sorted(missing)}")

    try:
        qty = int(row["qty"])
    except (TypeError, ValueError):
        raise OrderError(f"qty not an integer: {row['qty']!r}")
    if qty <= 0:
        raise OrderError(f"qty must be > 0, got {qty}")

    price = float(row["price"])
    if price < 0:
        raise OrderError(f"price must be >= 0, got {price}")

    return {"sku": str(row["sku"]), "qty": qty, "price": price}

