def has_duplicate_slow(items):
    """O(n squared): for each item, scan the WHOLE list again."""
    for i in range(len(items)):
        for j in range(len(items)):
            if i != j and items[i] == items[j]:
                return True
    return False


def has_duplicate_fast(items):
    """O(n): one pass; membership in a set is O(1) average."""
    seen = set()
    for item in items:
        if item in seen:   # O(1) lookup, NOT a second pass
            return True
        seen.add(item)
    return False


if __name__ == "__main__":
    print(has_duplicate_fast([]))        # edge case: empty -> False
    print(has_duplicate_fast([1, 2, 3])) # no dupes  -> False
    print(has_duplicate_fast([1, 2, 1])) # a dupe    -> True

import time
from solution import has_duplicate_slow, has_duplicate_fast


def test_same_answers():
    for case in ([], [1, 2, 3], [1, 2, 1], [7]):
        assert has_duplicate_slow(case) == has_duplicate_fast(case)


def test_empty_is_false():
    assert has_duplicate_fast([]) is False   # edge case, no crash


def test_fast_scales_better_than_slow():
    data = list(range(4000))          # no duplicates -> worst case

    t0 = time.perf_counter(); has_duplicate_slow(data);  slow = time.perf_counter() - t0
    t0 = time.perf_counter(); has_duplicate_fast(data);  fast = time.perf_counter() - t0

    # O(n) must beat O(n squared) by a wide margin at n=4000
    assert fast * 10 < slow, f"expected O(n) to crush O(n^2): fast={fast:.4f} slow={slow:.4f}"

