from collections import Counter


def count_frequencies(items):
    """Contract: items -> dict[str, int].

    In:  a list of strings (may be empty).
    Out: {item: count}; {} for an empty list.
    Raises TypeError on non-list / non-string input.
    """
    if not isinstance(items, list):
        raise TypeError(f"expected list, got {type(items).__name__}")
    counts = {}
    for item in items:
        if not isinstance(item, str):
            raise TypeError(f"expected str item, got {type(item).__name__}")
        counts[item] = counts.get(item, 0) + 1  # unseen -> 0, never KeyError
    return counts


assert count_frequencies(["a", "b", "a"]) == {"a": 2, "b": 1}
assert count_frequencies([]) == {}
assert count_frequencies(["x"]) == Counter(["x"])  # Counter is the stdlib twin

