from collections import deque

PAIRS = {")": "(", "]": "[", "}": "{"}

def is_balanced(text: str) -> bool:
    """LIFO: a closer must match the most recent opener."""
    stack: list[str] = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)          # push
        elif ch in PAIRS:
            if not stack or stack.pop() != PAIRS[ch]:
                return False          # pop mismatched or empty
    return not stack                  # leftover openers = unbalanced

def run_jobs(jobs: list[str]) -> list[str]:
    """FIFO: jobs run in arrival order — fairness invariant."""
    q: deque[str] = deque(jobs)
    order: list[str] = []
    while q:
        order.append(q.popleft())     # dequeue the head
    return order

def dequeue(q: deque[str]) -> str:
    if not q:
        raise IndexError("dequeue from empty queue")
    return q.popleft()

