import heapq
from typing import Iterable, List


def top_k(nums: Iterable[float], k: int) -> List[float]:
    """Return the k largest values, ascending. O(n log k) time, O(k) memory."""
    if not isinstance(k, int) or k < 0:
        raise ValueError(f"k must be a non-negative int, got {k!r}")
    if k == 0:
        return []

    heap: List[float] = []  # size-k MIN-heap; root = smallest kept
    for x in nums:
        if not isinstance(x, (int, float)):
            raise TypeError(f"non-numeric value in stream: {x!r}")
        if len(heap) < k:
            heapq.heappush(heap, x)
        elif x > heap[0]:            # beat the weakest survivor?
            heapq.heappushpop(heap, x)  # evict root, admit x, one op
    return sorted(heap)             # k items -> O(k log k), cheap

