from collections import deque

Graph = dict[str, list[str]]


def bfs_shortest_path(graph: Graph, start: str, goal: str) -> list[str] | None:
    """Return a fewest-hops path start->goal, or None if unreachable.
    Contract: graph is an adjacency list; start/goal are node keys."""
    if start not in graph:
        raise KeyError(f"start node {start!r} not in graph")
    queue: deque[list[str]] = deque([[start]])
    visited: set[str] = {start}
    while queue:
        path = queue.popleft()          # FIFO -> explores by ring
        node = path[-1]
        if node == goal:
            return path                 # first arrival = shortest
        for nbr in graph.get(node, []):
            if nbr not in visited:
                visited.add(nbr)
                queue.append(path + [nbr])
    return None


def dfs_reachable(graph: Graph, start: str) -> set[str]:
    """Return every node reachable from start. Stack-based, cycle-safe."""
    if start not in graph:
        raise KeyError(f"start node {start!r} not in graph")
    stack: list[str] = [start]
    visited: set[str] = set()
    while stack:
        node = stack.pop()              # LIFO -> plunges deep
        if node in visited:
            continue
        visited.add(node)
        stack.extend(graph.get(node, []))
    return visited

