def fib(n: int, memo: dict[int, int] | None = None) -> int:
    """Return the nth Fibonacci number (0-indexed) via memoization.

    Contract: n >= 0 integer -> int. Raises ValueError on n < 0.
    Overlapping subproblems are cached, so runtime is O(n), not O(2^n).
    """
    if not isinstance(n, int):
        raise TypeError(f"n must be int, got {type(n).__name__}")
    if n < 0:
        raise ValueError(f"n must be >= 0, got {n}")
    if memo is None:
        memo = {}
    if n < 2:
        return n
    if n in memo:
        return memo[n]
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]

