import os
import socket
import sys

ALLOWED_LEVELS = {"debug", "info", "warning", "error"}


def read_port(env: dict[str, str]) -> int:
    raw = env.get("PORT", "8080")
    try:
        port = int(raw)
    except ValueError:
        raise ValueError(f"PORT must be an integer, got {raw!r}")
    if not (1 <= port <= 65535):
        raise ValueError(f"PORT out of range 1..65535: {port}")
    return port


def read_level(env: dict[str, str]) -> str:
    level = env.get("LOG_LEVEL", "info").lower()
    if level not in ALLOWED_LEVELS:
        raise ValueError(f"LOG_LEVEL must be one of {sorted(ALLOWED_LEVELS)}, got {level!r}")
    return level


def bind_or_report(port: int) -> socket.socket:
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        sock.bind(("127.0.0.1", port))
    except OSError as err:
        sock.close()
        raise OSError(f"port {port} already in use") from err
    sock.listen()
    return sock


def main() -> int:
    try:
        port = read_port(os.environ)
        level = read_level(os.environ)
        sock = bind_or_report(port)
    except (ValueError, OSError) as err:
        print(f"startup failed: {err}", file=sys.stderr)
        return 1
    print(f"listening on 127.0.0.1:{port} (log level {level}) pid={os.getpid()}")
    sock.close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

